class Solution {
public:
    int trapRainWater(vector<vector<int>>& h) {
        int m = h.size(), n = h[0].size();
        vector<vector<char>> seen(m, vector<char>(n, 0));
        priority_queue<array<int,3>, vector<array<int,3>>, greater<array<int,3>>> pq;
        for (int i = 0; i < m; i++) for (int j = 0; j < n; j++)
            if (i == 0 || j == 0 || i == m - 1 || j == n - 1) { pq.push({h[i][j], i, j}); seen[i][j] = 1; }
        int water = 0; int dx[] = {1, -1, 0, 0}, dy[] = {0, 0, 1, -1};
        while (!pq.empty()) {
            auto [lv, i, j] = pq.top(); pq.pop();
            for (int d = 0; d < 4; d++) {
                int a = i + dx[d], b = j + dy[d];
                if (a < 0 || b < 0 || a >= m || b >= n || seen[a][b]) continue;
                seen[a][b] = 1; water += max(0, lv - h[a][b]);
                pq.push({max(lv, h[a][b]), a, b});
            }
        }
        return water;
    }
};

